/*
 * Stock firmware v1.13: the functions and variables our code uses.
 *
 * Part of hackai-mpk. Licensed under GPL-3.0-or-later.
 *
 * Functions are resolved by the linker from config/symbols.csv (build/mods/
 * stock.ld, generated by tools/build_mod.py), so a name here must exist there.
 * The stock firmware is built with IAR, which follows the AAPCS like GCC.
 * RAM variables are fixed addresses found during the analysis, see docs/.
 */
#ifndef HK_STOCK_H
#define HK_STOCK_H

#include <stdint.h>

/* --- Display (docs/display.md, docs/menus.md) ----------------------------- */

/* Draws a string with a font; invert = 1 for highlighted text. */
void print_LCD_APP(uint16_t x, uint16_t y, const char *str, const uint8_t *font,
                   uint8_t invert);
void framebuffer_clear_APP(void);
void menu_title_rule_APP(void);

/* Menu font: byte 0 = character width, byte 1 = row height (10 x 10). */
#define FONT_MENU ((const uint8_t *)0x08025810)

/* --- Menus (docs/menus.md) ------------------------------------------------ */

#define UI_SCREEN    (*(volatile uint8_t *)0x20004DA8) /* current screen id */
#define UI_EDIT      (*(volatile uint8_t *)0x20004DAE) /* 0 choose entry, 1 edit value */
#define UI_CURSOR    (*(volatile uint8_t *)0x20004DAF) /* entry number */
#define UI_STATE     (*(volatile uint8_t *)0x20004DA6) /* 1 temporary, 2 normal, 3 screensaver */

#define SCREEN_GLOBAL 0x16

/* 64-bit tick counter (20 us) and time of the last activity (screensaver). */
#define TICKS_NOW           ((volatile uint32_t *)0x20004CB8)
#define TICKS_LAST_ACTIVITY ((volatile uint32_t *)0x20004BF0)

void transpose_apply_POSSIBLE_APP(void);

/* --- Current program (docs/programs.md) ----------------------------------- */

#define PROGRAM ((volatile uint8_t *)0x20000668)
#define PROG_PAD_CHANNEL   0x10  /* 0-15 */
#define PROG_PAD_AFTERTOUCH 0x11 /* 0 Off, 1 Chan, 2 Poly */
#define PROG_MIDI_CHANNEL  0x12  /* 0-15 */
#define PROG_TRANSPOSE     0x14  /* 0-24, 12 = none */
#define PROG_TPRT          0x15  /* 0-1 */
#define PROG_TAPS          0x1C  /* 2-4 */

/* --- Flash (docs/updater.md for the controller) --------------------------- */

#define FLASH_OK 4  /* return value of the erase/program functions */

void flash_unlock(void);
void flash_lock(void);
void flash_flag_clear(uint32_t flags);
uint8_t flash_sector_erase_APP(uint32_t address);
uint8_t flash_word_program_APP(volatile uint32_t *address, uint32_t value);

#define FLASH_FLAGS_ALL 0x34  /* PRGMERR | EPPERR | ODF, as the stock code clears */

#endif
